WFJ.Data.add("gossip", {
  ["fc0512bc6654c09f"] = { "Ilifar, il tuo padrone ti chiama!", "." },
  ["fc094251053c2cff"] = { "Il sapere è al tempo stesso strumento e arma per chi ha la volontà di usarlo.", "." },
  ["fc0a633df460d182"] = { "Vuoi fondare una gilda, eh? Allora buona fortuna!\n\nParla con Aldwin Laughlin al Visitor's Center di ⟦Stormwind=Roccavento⟧. È nel ⟦Trade District=Quartiere del Commercio⟧, appena entri dalla ⟦Valley of Heroes=Valle degli Eroi⟧.", "." },
  ["fc0b9e03154e3f94"] = { "Le stelle mi parlano. Mi sussurrano degli orrori che attendono nella notte.", "." },
  ["fc12fca17e1b19e2"] = { "Quelli come te, {race}, vogliono solo la mia erba.", "." },
  ["fc161c5e11c25dab"] = { "Ehi, ehi, piano, amico mio. Un momento...", "." },
  ["fc1eab167c5d60f9"] = { "Se vuoi imparare la professione di Conciatura, dovrai andare a ⟦Ironforge=Forgiardente⟧. Ho sentito che c'è una bella bottega vicino alla ⟦Great Forge=Grande Forgia⟧ dove puoi impararla.", "." },
  ["fc3548dc2524d9dc"] = { "SMOTTS, HO LA TUA CINTURINA... VIENI A PRENDERLA.", "." },
  ["fc35dbd2eba05a2c"] = { "La Hall of Spirits è la casa dei nostri sciamani. La trovi sull'⟦Spirit Rise=Altura degli Spiriti⟧. Che i tuoi antenati veglino su di te.", "." },
  ["fc3a602c449b2f49"] = { "Ho sentito che i troll del ⟦Sen'jin Village=Villaggio di Sen'jin⟧ hanno un preparatore di pozioni di nome Miao'zan. Cerca lì.", "." },
  ["fc42ea199c54b608"] = { "Eunice Burch vendere pezzi avanzati. Tu trovare lei in ⟦Trade Quarter=Quartiere del Commercio⟧.", "." },
  ["fc44303c0f91e104"] = { "Salute, <ragazzo/ragazza>. Sono ⟦Grelin Whitebeard=Grelin Barbabianca⟧. Sono qui per valutare la minaccia rappresentata dal numero crescente di troll nella ⟦Coldridge Valley=Valle Crestafredda⟧. Cosa ho scoperto? È un po' preoccupante...", "." },
  ["fc4f3bba7130783c"] = { "Le macchine d'assedio sono l'orgoglio di ogni pilota!", "." },
  ["fc504de7d1b43afd"] = { "Proprio così. Nefarian, progenie di Alamorte, ora governa i Bastioni. Rend è agli ordini del drago.\n\nSe solo riuscissi in qualche modo a passare per le Sale dell'Ascesa.\n\n<Eitrigg sospira.>\n\nAhimè, solo chi lo Stormo dei Draghi Neri ritiene degno ottiene il privilegio di ascendere.", "." },
  ["fc55f2c80130098c"] = { "Ottimo lavoro. Sei <pronto/pronta> a compiere una missione per conto mio? Non conosco nessuno più qualificato di te.", "." },
  ["fc5c563e57a41ffa"] = { "Ignorando la battaglia che infuriava intorno a lui, Latherion abbassò la guardia per stringere a sé la sua amata nei suoi ultimi istanti. Ma i demoni non gli diedero tregua e lo abbatterono in fretta.", "." },
  ["fc66a30bb66c3957"] = { "Hai rovinato le tue terre, non rovinerai le mie.", "." },
  ["fc6be0c44b370b9f"] = { "Le statue sono tutte al loro posto: puoi iniziare l'enigma.", "." },
  ["fc71bc9fcde46829"] = { "Andare in anello interno di ⟦War Quarter=Quartiere della Guerra⟧. Brom Killian là.", "." },
  ["fc72c5dd91e29958"] = { "Adoro il mattino! È una giornata splendida, vero? Senti che aria?", "." },
  ["fc810c7435b94c1d"] = { "Tenente, ho perso le mie insegne. Potresti darmene di nuove, per favore?", "." },
  ["fc81fef6cf21195c"] = { "Curioso. Un servitore di Rastakhan che non sa che gli Hakkari non conversano nella lingua antica?", "." },
  ["fc89cc857b22f5ba"] = { "Alla casa! Restami vicino, qualunque cosa succeda! Lì ho il fucile e le munizioni!", "." },
  ["fc8dea293bfd1f12"] = { "Viviamo in un mondo di tragedie senza fine.", "." },
  ["fc91263ebe777dc1"] = { "Il torio incantato è un metallo molto ricercato. La tua migliore occasione per trovarne è parlare con un fabbro artigiano o un minatore.", "." },
  ["fca429426926a992"] = { "Questa entità demoniaca è nota come ombra del Vuoto. La sua forza e la sua resistenza sono notevoli, il che la rende ideale per la difesa. Mandala ad attaccare il nemico, poi usala come scudo mentre i tuoi incantesimi e le tue abilità prosciugano la vita dell'avversario.", "." },
  ["fcafb51f5f862977"] = { "Non ne conosco nessuno da queste parti. Ti conviene andare a Orgrimmar, a nord, e chiedere a uno dei loro soldati.", "." },
  ["fcb07d5784ceb506"] = { "Lo senti, Mulv? Il bisogno? Devi volerlo, prima che io possa darti l'ordine. Ma chi voglio prendere in giro? Vai là fuori!", "." },
  ["fcb52914c8eec0a8"] = { "Faresti meglio a trattenermi, o {name} assaggerà un pestaggio da galera.", "." },
  ["fcb90cd3b6387983"] = { "Il male mi fa venire così sonno...", "." },
  ["fcbce68fa4fd3dd0"] = { "Thurman, fratello mio, chi ride adesso? Ah!", "." },
  ["fcc0411d6c9a32bc"] = { "Guarda dove metti i piedi...", "." },
  ["fcc10b39451bc6f6"] = { "I silvagufi sono intrinsecamente magici: questo potere fu loro concesso dalla dea.", "." },
  ["fccb9166dec2a601"] = { "Proprio mentre parliamo, {class}, tutto il materiale bellico viene trasportato a ⟦Silithus=Silitus⟧. A quanto pare, dovrebbe arrivare tutto in meno di $2113w giorni. Dopodiché, <un/una> <eroe/eroina> dovrà venire a suonare il gong sull'Altare dello Scarabeo. Allora la guerra comincerà davvero.", "." },
  ["fcde299ee09a41b6"] = { "{name}, se sei qui per far verificare il compito che ti è stato affidato, allora benissimo: sono dieci scaglie dei Crestaostile quelle che cerco. Se sei qui per fare due chiacchiere, al momento non ho tempo per simili futilità.\n\nSappi questo: noi elfi della notte non siamo guerrafondai. La nostra razza è votata alla conservazione della pace e dell'armonia. Questo però non significa che non proteggeremo i nostri interessi in modo attivo. È il mio dovere verso la generale Feathermoon e verso la roccaforte.", "." },
  ["fce10d345babce67"] = { "Ti do il benvenuto a ⟦Bandarion Keep=Forte Bandarion⟧, {class}.", "." },
  ["fce1f623120a24a8"] = { "Salute, {class}. Sii breve nel dire in che modo il Kirin Tor può esserti utile.", "." },
  ["fcf718e1109fed61"] = { "Con tutti questi mercanti che arrivano qui e in tutta Azeroth, c'è meno disponibilità del materiale che usiamo per fare i vestiti ai bambini del nostro orfanotrofio. Aiutarmi a raccogliere il lino perché mia moglie possa fare loro dei vestiti nuovi è molto nobile da parte tua, {name}. Grazie.\n\nSpero di poter tornare presto a casa da mia moglie.", "." },
  ["fcf731edf32258c2"] = { "Alt.", "." },
  ["fcf849726aa15802"] = { "Mau'ari sapere perché tu cercare lei...\n\nPortami gli E'ko che trovi nel mondo, e io posso trasformarli per te.", "." },
})
